function createDragger() {
    Draggable.create("#dragger", {
        type: "x",
        bounds: {
            minX: 0,
            maxX: 520
        },
        throwProps: true,
        edgeResistance: 1,
        onDrag: moveMask,
        onThrowUpdate: moveMask
    });
}

function moveMask() {
    TweenMax.set("#theSquare", {attr: {x: this.x - 520}});
}
function artChart(id, data, dv){
    new Chart(id, {
        type: 'bar',
        data: data,
        options: {
            indexAxis: 'y',
            scales: {
                x: {
                    grid: {
                        display: false
                    },
                    ticks: {
                        callback: function(value, index, ticks) {
                            let max =  ticks[ticks.length-1].value 
                            if (value === max) {
                                return dv == "km" ? value.toLocaleString("es-CO") + '     km' : value.toLocaleString("es-CO") + '     tỷ đồng';
                              } else {
                                return value.toLocaleString("es-CO")
                              }
                        },
                        font:{
                            size: "17px",
                            weight: 400,
                        },
                        color: "#000"
                    }
                },
                y: {
                    grid: {
                        display: false
                    },
                    ticks:{
                        font:{
                            size: "17px",
                            weight: 500,
                        },
                        color: "#000"
                    }
                }
            },
            plugins: {
                legend:{
                    display: false,
                    labels: {
                        font:{
                            style: 'bold',
                            weight: '600'
                        }
                    }
                },
                datalabels: {
                    formatter: function(value, context) {
                        if(context.active === true){
                            return "";
                        }else{
                            return value.toLocaleString("es-CO")
                        }
                    }, 
                    font:{
                        size: "17px",    
                    }
                    
                },
                tooltip: {
                    callbacks: {
                        label: function (context) {
                            let label = '';
                            if (context.parsed.x !== null) {
                                label += context.parsed.x.toLocaleString("es-CO")
                            }
                            return label;
                        }
                    }
                }
            }
        },
        plugins:[ChartDataLabels],
    });
}